script.lang:
ALTER TABLE amp_indicator_global_value ADD COLUMN IF NOT EXISTS activity_location BIGINT;
CREATE INDEX IF NOT EXISTS amp_indicator_global_value_activity_location_idx
    ON amp_indicator_global_value (activity_location);
CREATE TABLE IF NOT EXISTS amp_disagg_actual_values (
    disagg_value_id BIGINT NOT NULL REFERENCES amp_indicator_disaggregation_values(id),
    global_value_id BIGINT NOT NULL REFERENCES amp_indicator_global_value(id),
    PRIMARY KEY (disagg_value_id, global_value_id)
);
